insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('018773eb-609e-48ab-beee-5366974e0f24', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', null, 'topic'::public.curated_course_node_type, 'Religious Ethics as an Academic Field', 'This opening section defines religious ethics as a comparative, historical, textual, philosophical, and lived field of study. The point is to see ethical claims as embedded in communities, practices, authorities, and disputes rather than as isolated opinions.', 0),
  ('7019ddbe-8ba8-4420-b59b-e4722f86dde5', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '018773eb-609e-48ab-beee-5366974e0f24', 'subtopic'::public.curated_course_node_type, 'Defining Religious Ethics', 'Students learn what makes an ethical question religiously meaningful and how the field differs from theology, philosophy, anthropology, and professional applied ethics.', 0),
  ('5741949d-a769-4411-bc7a-1611f6e3669d', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '7019ddbe-8ba8-4420-b59b-e4722f86dde5', 'concept'::public.curated_course_node_type, 'Moral norms, virtues, practices, and ultimate goods', null, 0),
  ('a35e2700-8c7e-4404-8227-b773d25908a1', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '7019ddbe-8ba8-4420-b59b-e4722f86dde5', 'concept'::public.curated_course_node_type, 'Descriptive, interpretive, normative, and constructive approaches', null, 1),
  ('ea8c051b-0bbf-4348-aaec-86e7be4764f3', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '7019ddbe-8ba8-4420-b59b-e4722f86dde5', 'concept'::public.curated_course_node_type, 'Insider and outsider vocabularies', null, 2),
  ('31172b64-5953-4c73-b40c-0c43b94b6ca1', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '7019ddbe-8ba8-4420-b59b-e4722f86dde5', 'concept'::public.curated_course_node_type, 'Tradition, change, and moral disagreement', null, 3),
  ('87dafb27-7b60-4834-99ea-56627f24a664', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '018773eb-609e-48ab-beee-5366974e0f24', 'subtopic'::public.curated_course_node_type, 'Academic Study of Religion and Ethics', 'This subtopic grounds ethical analysis in the broader academic study of religion, including attention to power, context, comparison, and evidence.', 1),
  ('b914c454-9736-46cf-ba81-55f66d95b5fc', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '87dafb27-7b60-4834-99ea-56627f24a664', 'concept'::public.curated_course_node_type, 'Myth, ritual, symbol, text, law, and community', null, 0),
  ('9cf543ba-7d11-42e9-859f-443f2891e462', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '87dafb27-7b60-4834-99ea-56627f24a664', 'concept'::public.curated_course_node_type, 'Lived religion and everyday moral practice', null, 1),
  ('ea2bf1ef-9630-493c-a416-a45efe987389', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '87dafb27-7b60-4834-99ea-56627f24a664', 'concept'::public.curated_course_node_type, 'Historical-critical and ethnographic evidence', null, 2),
  ('dfab163f-03d1-466d-81c9-5491f7c3d8c8', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '87dafb27-7b60-4834-99ea-56627f24a664', 'concept'::public.curated_course_node_type, 'Avoiding reductionism and romanticization', null, 3),
  ('5ec5304b-d148-4a7c-8b67-aff70a55ef97', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '018773eb-609e-48ab-beee-5366974e0f24', 'subtopic'::public.curated_course_node_type, 'Moral Problems as Case Studies', 'Students practice turning real ethical conflicts into analyzable cases with facts, stakeholders, values, traditions, and possible judgments.', 2),
  ('840e3298-937b-4730-9586-ec0b76fa4081', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5ec5304b-d148-4a7c-8b67-aff70a55ef97', 'concept'::public.curated_course_node_type, 'Fact patterns and competing goods', null, 0),
  ('284c6fc8-2ae4-4989-85fa-5af1933402d7', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5ec5304b-d148-4a7c-8b67-aff70a55ef97', 'concept'::public.curated_course_node_type, 'Stakeholder mapping and moral salience', null, 1),
  ('e9f2f63b-6ea2-4d95-a71f-771b154773b2', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5ec5304b-d148-4a7c-8b67-aff70a55ef97', 'concept'::public.curated_course_node_type, 'Norms, precedents, and practical wisdom', null, 2),
  ('69664a59-10d2-4fad-a79a-514c0df3d090', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5ec5304b-d148-4a7c-8b67-aff70a55ef97', 'concept'::public.curated_course_node_type, 'Writing a defensible ethical conclusion', null, 3),
  ('857d3263-7cbb-46de-afad-db7c0985a12a', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', null, 'topic'::public.curated_course_node_type, 'Sources of Moral Authority in Religious Traditions', 'Religious ethics depends on what a community treats as authoritative. This section teaches students to identify sources of authority and evaluate how they are interpreted, ranked, contested, and revised.', 1),
  ('3cbfeedb-3e97-40f0-8103-4e10f90c485c', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '857d3263-7cbb-46de-afad-db7c0985a12a', 'subtopic'::public.curated_course_node_type, 'Scripture, Revelation, and Sacred Narrative', 'Students examine how texts and stories authorize moral claims and how interpretation mediates between ancient sources and present decisions.', 0),
  ('e63753f9-9b33-4bb6-91d5-164297de1cbc', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '3cbfeedb-3e97-40f0-8103-4e10f90c485c', 'concept'::public.curated_course_node_type, 'Canon, commentary, and translation', null, 0),
  ('bcdfd429-38f7-4042-9157-ea07c2381d4e', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '3cbfeedb-3e97-40f0-8103-4e10f90c485c', 'concept'::public.curated_course_node_type, 'Narrative exemplars and moral imagination', null, 1),
  ('7e64c9ea-c4c0-4b11-996d-2ba52c101ba9', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '3cbfeedb-3e97-40f0-8103-4e10f90c485c', 'concept'::public.curated_course_node_type, 'Proof-texting versus contextual interpretation', null, 2),
  ('410747ce-3003-476a-84d7-67ae66f67ef8', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '3cbfeedb-3e97-40f0-8103-4e10f90c485c', 'concept'::public.curated_course_node_type, 'Disputes over literal, allegorical, and historical readings', null, 3),
  ('c17efef6-ff00-42b3-8793-096e7e4efd40', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '857d3263-7cbb-46de-afad-db7c0985a12a', 'subtopic'::public.curated_course_node_type, 'Law, Command, Conscience, and Community', 'This subtopic shows how commands and laws function within communities and how conscience can affirm, challenge, or refine inherited norms.', 1),
  ('7c89e5c8-af76-493b-b518-72333de55033', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', 'c17efef6-ff00-42b3-8793-096e7e4efd40', 'concept'::public.curated_course_node_type, 'Divine command and covenant obligations', null, 0),
  ('69090247-0e4f-4105-a3c7-12fc353ae564', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', 'c17efef6-ff00-42b3-8793-096e7e4efd40', 'concept'::public.curated_course_node_type, 'Religious law and jurisprudence', null, 1),
  ('0fbd5efd-a20f-4107-a684-fd821fb0f098', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', 'c17efef6-ff00-42b3-8793-096e7e4efd40', 'concept'::public.curated_course_node_type, 'Conscience, discernment, and moral agency', null, 2),
  ('d23a4322-21d5-45ac-9d41-ed44463ce838', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', 'c17efef6-ff00-42b3-8793-096e7e4efd40', 'concept'::public.curated_course_node_type, 'Authority of clergy, teachers, elders, and institutions', null, 3),
  ('5ac7a4ea-9d1f-4974-b230-beb20790e30a', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '857d3263-7cbb-46de-afad-db7c0985a12a', 'subtopic'::public.curated_course_node_type, 'Reason, Experience, Tradition, and Practice', 'Students explore sources that are not reducible to scripture, including philosophical reason, spiritual experience, communal practice, and historical memory.', 2),
  ('61ea0c37-eae0-4ff9-8538-2327e3273a59', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5ac7a4ea-9d1f-4974-b230-beb20790e30a', 'concept'::public.curated_course_node_type, 'Natural law and practical reason', null, 0),
  ('0de025eb-3d86-4b88-9ef4-eb11cdcf2949', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5ac7a4ea-9d1f-4974-b230-beb20790e30a', 'concept'::public.curated_course_node_type, 'Experience, testimony, and moral insight', null, 1),
  ('6ab3415e-030a-4e1e-a87c-d6fbaa2df7b1', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5ac7a4ea-9d1f-4974-b230-beb20790e30a', 'concept'::public.curated_course_node_type, 'Custom, precedent, and embodied practice', null, 2),
  ('4e8df1a3-989e-4299-864a-230320362ce6', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5ac7a4ea-9d1f-4974-b230-beb20790e30a', 'concept'::public.curated_course_node_type, 'Tradition as continuity and argument', null, 3),
  ('59f3fa28-e4a4-4904-84e3-068592b1dbe0', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', null, 'topic'::public.curated_course_node_type, 'Normative Ethical Frameworks and Moral Reasoning', 'This section gives students a portable toolkit for comparing moral arguments. The goal is not to force traditions into one framework, but to recognize recurring structures of reasoning.', 2),
  ('7cbe15a3-4a66-4364-8957-a8d527d33089', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '59f3fa28-e4a4-4904-84e3-068592b1dbe0', 'subtopic'::public.curated_course_node_type, 'Virtue, Character, and Moral Formation', 'Virtue ethics asks what kind of person or community one should become and how habits, exemplars, and disciplines cultivate moral excellence.', 0),
  ('06d21690-7a4b-4942-9afc-aed94ca55331', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '7cbe15a3-4a66-4364-8957-a8d527d33089', 'concept'::public.curated_course_node_type, 'Virtues, vices, and moral exemplars', null, 0),
  ('0320f205-2ca0-4d29-9e25-757632dfefdd', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '7cbe15a3-4a66-4364-8957-a8d527d33089', 'concept'::public.curated_course_node_type, 'Habit, discipline, worship, and practice', null, 1),
  ('1efac465-fdae-4210-a72a-2c8ca4cf4674', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '7cbe15a3-4a66-4364-8957-a8d527d33089', 'concept'::public.curated_course_node_type, 'Character and community formation', null, 2),
  ('d5a9f270-a21d-4e2e-a347-d61175935b28', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '7cbe15a3-4a66-4364-8957-a8d527d33089', 'concept'::public.curated_course_node_type, 'Practical wisdom and moral perception', null, 3),
  ('b68e3a71-111f-4102-9b89-459f58a4f0b2', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '59f3fa28-e4a4-4904-84e3-068592b1dbe0', 'subtopic'::public.curated_course_node_type, 'Law, Duty, Command, and Obligation', 'Duty-centered reasoning highlights requirements, prohibitions, rights, promises, and obedience to divine or communal authority.', 1),
  ('314c56b1-822d-46ff-b8e0-b8800a1b7380', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', 'b68e3a71-111f-4102-9b89-459f58a4f0b2', 'concept'::public.curated_course_node_type, 'Deontology and moral rules', null, 0);
