  ('9260cbea-6fed-4f4e-bd62-598fa4a38c6d', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', 'b68e3a71-111f-4102-9b89-459f58a4f0b2', 'concept'::public.curated_course_node_type, 'Conflict between duties', null, 3),
  ('2f900ae3-dd36-48b0-a49c-d2cff227c848', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '59f3fa28-e4a4-4904-84e3-068592b1dbe0', 'subtopic'::public.curated_course_node_type, 'Consequences, Care, Liberation, and Justice', 'Students learn frameworks that judge actions by outcomes, relationships, oppression, repair, and the distribution of benefits and burdens.', 2),
  ('daf5fb08-3a36-4f74-9690-d6e5384cd3d2', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '2f900ae3-dd36-48b0-a49c-d2cff227c848', 'concept'::public.curated_course_node_type, 'Consequentialism and public goods', null, 0),
  ('f3624497-ee8e-4426-bf37-89630e5c607e', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '2f900ae3-dd36-48b0-a49c-d2cff227c848', 'concept'::public.curated_course_node_type, 'Care ethics and relational responsibility', null, 1),
  ('186afca0-45e1-44bd-b1a6-ad94aba00030', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '2f900ae3-dd36-48b0-a49c-d2cff227c848', 'concept'::public.curated_course_node_type, 'Liberationist and anti-oppressive ethics', null, 2),
  ('d07a6359-9fc7-47e6-b506-8c988140a176', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '2f900ae3-dd36-48b0-a49c-d2cff227c848', 'concept'::public.curated_course_node_type, 'Distributive, procedural, and restorative justice', null, 3),
  ('96362db0-5e9a-4017-9f58-64b40ec6c346', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', null, 'topic'::public.curated_course_node_type, 'Scripture, Interpretation, and Moral Argument', 'Religious ethics often turns on how texts are read. This section trains students to analyze interpretive moves, historical contexts, and moral uses of scripture.', 3),
  ('0cc602d5-5f36-489b-a2bf-4e32e9e95cf4', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '96362db0-5e9a-4017-9f58-64b40ec6c346', 'subtopic'::public.curated_course_node_type, 'Hermeneutics and Context', 'Students learn that ethical interpretation requires context: language, genre, history, audience, and the community of reception.', 0),
  ('064b59d7-82f3-496a-ae06-c86727f12546', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '0cc602d5-5f36-489b-a2bf-4e32e9e95cf4', 'concept'::public.curated_course_node_type, 'Genre, narrative, poetry, law, and wisdom literature', null, 0),
  ('3360f1d7-d870-43c7-b306-bfe5e68c5949', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '0cc602d5-5f36-489b-a2bf-4e32e9e95cf4', 'concept'::public.curated_course_node_type, 'Historical setting and social world', null, 1),
  ('8c5f15dd-dc47-40ee-8a9d-cb5e44663a2b', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '0cc602d5-5f36-489b-a2bf-4e32e9e95cf4', 'concept'::public.curated_course_node_type, 'Reception history and commentary traditions', null, 2),
  ('50ee06d1-8748-459e-b42a-7f28ca23737f', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '0cc602d5-5f36-489b-a2bf-4e32e9e95cf4', 'concept'::public.curated_course_node_type, 'Translation and semantic range', null, 3),
  ('20217f02-1072-4a46-ace5-afe3258504e5', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '96362db0-5e9a-4017-9f58-64b40ec6c346', 'subtopic'::public.curated_course_node_type, 'Interpretive Conflict', 'Religious communities often disagree about the moral meaning of the same source. This subtopic teaches students to compare arguments fairly.', 1),
  ('4aa70e10-7da2-4f80-9888-4c19b2141a7f', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '20217f02-1072-4a46-ace5-afe3258504e5', 'concept'::public.curated_course_node_type, 'Competing canons of interpretation', null, 0),
  ('2103ba18-f73c-4b1e-b667-0f98e147687b', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '20217f02-1072-4a46-ace5-afe3258504e5', 'concept'::public.curated_course_node_type, 'Continuity, reform, and rupture', null, 1),
  ('7bc317d6-56a7-4822-af06-4ae60044f3a8', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '20217f02-1072-4a46-ace5-afe3258504e5', 'concept'::public.curated_course_node_type, 'Minority readings and contested authority', null, 2),
  ('4f9d7e6f-3fad-4936-9959-dc7b3704ae95', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '20217f02-1072-4a46-ace5-afe3258504e5', 'concept'::public.curated_course_node_type, 'Ethical stakes of interpretation', null, 3),
  ('07ab6b02-3ae0-4537-83c4-110822053128', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '96362db0-5e9a-4017-9f58-64b40ec6c346', 'subtopic'::public.curated_course_node_type, 'From Text to Contemporary Judgment', 'Students practice moving from ancient or classical sources to modern cases without ignoring historical distance or present complexity.', 2),
  ('ce29e3c9-3213-472d-bf05-e9d4d4085098', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '07ab6b02-3ae0-4537-83c4-110822053128', 'concept'::public.curated_course_node_type, 'Analogy and precedent', null, 0),
  ('ce030554-583c-4db6-9aff-598df6462afa', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '07ab6b02-3ae0-4537-83c4-110822053128', 'concept'::public.curated_course_node_type, 'Principles versus rules', null, 1),
  ('b729d83d-908e-46ce-8008-7556ae29b5f5', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '07ab6b02-3ae0-4537-83c4-110822053128', 'concept'::public.curated_course_node_type, 'Casuistry and case comparison', null, 2),
  ('334c8b34-c593-4881-8f68-b4441049928c', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '07ab6b02-3ae0-4537-83c4-110822053128', 'concept'::public.curated_course_node_type, 'Public reasoning from particular traditions', null, 3),
  ('8787d745-a70b-47aa-b286-9a34568e115d', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', null, 'topic'::public.curated_course_node_type, 'Ritual, Formation, Virtue, and Moral Community', 'This section treats ethics as formed through bodies, habits, rituals, institutions, and communal life. Students learn why moral knowledge is often practiced before it is abstracted.', 4),
  ('1681714c-0cd8-4098-ba3d-832209095191', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '8787d745-a70b-47aa-b286-9a34568e115d', 'subtopic'::public.curated_course_node_type, 'Ritual and Habit', 'Ritual can train attention, desire, memory, gratitude, restraint, and responsibility. Students ask how repeated practice shapes moral perception.', 0),
  ('ae65af4f-50e1-47f0-be3d-b285d0eeb294', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '1681714c-0cd8-4098-ba3d-832209095191', 'concept'::public.curated_course_node_type, 'Prayer, fasting, pilgrimage, confession, and service', null, 0),
