  ('a073c81b-4719-4951-bf70-410533df08cc', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '8e268e16-65ff-4197-b2d8-f7c6084d2d70', 'subtopic'::public.curated_course_node_type, 'Methods of Comparison', 'Students learn how to compare ethical concepts without assuming that similar words mean identical things across traditions.', 0),
  ('f63ee958-02dc-46e4-aab0-ab66f34cfe3b', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', 'a073c81b-4719-4951-bf70-410533df08cc', 'concept'::public.curated_course_node_type, 'Functional, genealogical, and thematic comparison', null, 0),
