  ('4d9ac1d7-1b49-495f-a9b3-1e974f565447', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', null, 'topic'::public.curated_course_node_type, 'Violence, War, Peace, and Nonviolence', 'This section examines religious arguments about violence, protection, punishment, self-defense, peace, reconciliation, and repair. Students learn to distinguish ethical ideals from institutional and historical realities.', 12),
  ('5f3e0ba8-f281-43be-a3f1-2d35a818f7d4', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '4d9ac1d7-1b49-495f-a9b3-1e974f565447', 'subtopic'::public.curated_course_node_type, 'Just War, Holy War, and Moral Limits', 'Students compare traditions that permit force under strict conditions and ask how moral limits are defined and enforced.', 0),
