  ('f8ca6c0d-a89d-4938-9ab5-af38c1722431', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '5f3e0ba8-f281-43be-a3f1-2d35a818f7d4', 'concept'::public.curated_course_node_type, 'Terrorism, state violence, and religious legitimation', null, 3),
  ('1b8fb269-c0b4-4c90-b628-0d725d4fdbe8', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '4d9ac1d7-1b49-495f-a9b3-1e974f565447', 'subtopic'::public.curated_course_node_type, 'Pacifism, Nonviolence, and Resistance', 'This subtopic studies nonviolence as discipline, strategy, witness, and spiritual practice.', 1),
