  ('69773bc4-af14-43eb-9fa5-3c8b8a9a8c39', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', 'b65a1f8e-c214-40f8-89f6-46850bb0558b', 'concept'::public.curated_course_node_type, 'Reconciliation without impunity', null, 3),
  ('289ad3a2-ff68-4d72-8e6d-b5d4d6f6b002', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', null, 'topic'::public.curated_course_node_type, 'Economic Justice, Poverty, Work, and Global Inequality', 'Religious traditions offer rich but contested moral visions of property, labor, wealth, poverty, charity, debt, and justice. Students connect personal obligation with structural analysis.', 13),
