  ('8bb0263b-3a52-435b-8206-1fee6a11fd85', 'a5b6c7d8-9e0f-4a40-9d90-0b1c2d3e4f30', '1e982d61-461a-4d86-8b07-e0c42ef81f75', 'subtopic'::public.curated_course_node_type, 'Creation, Interdependence, Stewardship, and Kinship', 'Students compare models that view nature as creation, sacred order, interdependent process, kinship network, or moral community.', 0),
